function isOpen(issue: Issue): boolean {
  return "'!CLOSED_ISSUE_STATUSES.includes(issue.status);
}

/** Traverse through archived nodes as well: live descendants still belong to the tree. */
function collectDescendants(all: readonly Issue[], issueId: IssueId): Issue[] {
  const children = new Map<IssueId, Issue[]>();
  for (const issue of all) {
    if (issue.parentId !== null) {
      const bucket = children.get(issue.parentId) ?? [];
      bucket.push(issue);
      children.set(issue.parentId, bucket);
    }
  }
  const result: Issue[] = [];
  const seen = new Set<IssueId>([issueId]);
  const pending = [...(children.get(issueId) ?? [])];
  while (pending.length > 0) {
    const child = pending.pop()!;
    if (seen.has(child.id)) continue;
    seen.add(child.id);
    result.push(child);
    pending.push(...(children.get(child.id) ?? []));
  }
  return result;
}

async function validateParent(orgId: OrgId, projectId: ProjectId, parentId: IssueId, issue: Issue | null): Promise<void> {
  const parent = await issueRepo.findIssueById(orgId, parentId);
  if (!parent || parent.projectId !== projectId) throw new NotFoundError("Issue", parentId);
  assertNotArchived("Issue", parent.id, parent);
  const all = await issueRepo.listProjectHierarchy(orgId, projectId);
  const byId = new Map(all.map((item) => [item.id, item]));
  const descendants = issue ? collectDescendants(all, issue.id) : [];
  if (issue && (parent.id === issue.id || descendants.some((item) => item.id === parent.id))) {
    throw new IssueHierarchyError(issue.id, "cycle");
  }
  let depth = 1;
  let ancestor: Issue | undefined = parent;
  const seen = new Set<IssueId>();
  while (ancestor) {
    if (seen.has(ancestor.id)) throw new IssueHierarchyError(issue?.id ?? parentId, "cycle");
    seen.add(ancestor.id);
    if (ancestor.parentId === null) break;
    depth++;
    ancestor = byId.get(ancestor.parentId);
  }
  let height = 0;
  for (const descendant of descendants) {
    let distance = 0;
    let node: Issue | undefined = descendant;
    while (node && node.id !== issue!.id && distance <= all.length) {
      distance++;
      node = node.parentId === null ? undefined : byId.get(node.parentId);
    }
    height = Math.max(height, distance);
  }
  if (depth + height > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(issue?.id ?? parentId, "too_deep");
  }
}

export async function setIssueParent(actor: Actor, input: SetIssueParentInput): Promise<Issue> {
  assertOrgScope(actor, input.orgId);
  const issue = requireFound(await issueRepo.findIssueById(input.orgId, input.issueId), "Issue", input.issueId);
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);
  if (input.parentId !== null) await validateParent(input.orgId, issue.projectId, input.parentId, issue);
  if (issue.parentId === input.parentId) return issue;
  const after = await issueRepo.setIssueParent(input.orgId, issue.id, input.parentId);
  await emit("issue.updated", { ...actorEnvelope(actor), issueId: after.id, projectId: after.projectId, changedFields: ["parentId"] });
  return after;
}

async function readHierarchy(actor: Actor, orgId: OrgId, issueId: IssueId): Promise<{ issue: Issue; all: readonly Issue[] }> {
  assertOrgScope(actor, orgId);
  const issue = requireFound(await issueRepo.findIssueById(orgId, issueId), "Issue", issueId);
  assertCan(actor, "issue:read", issueResource(issue));
  return { issue, all: await issueRepo.listProjectHierarchy(orgId, issue.projectId) };
}

export async function listSubIssues(actor: Actor, orgId: OrgId, issueId: IssueId): Promise<readonly Issue[]> {
  const { all } = await readHierarchy(actor, orgId, issueId);
  return all.filter((item) => item.parentId === issueId && item.archivedAt === null)
    .sort((a, b) => a.createdAt.localeCompare(b.createdAt) || a.number - b.number);
}

export async function getIssueRollup(actor: Actor, orgId: OrgId, issueId: IssueId): Promise<IssueRollup> {
  const { all } = await readHierarchy(actor, orgId, issueId);
  const live = collectDescendants(all, issueId).filter((item) => item.archivedAt === null);
  const open = live.filter(isOpen).length;
  return { total: live.length, open, closed: live.length - open };
}

async function notifyParentIfCompleted(actor: Actor, child: Issue): Promise<void> {
  if (child.parentId === null) return;
  const parent = await issueRepo.findIssueById(actor.orgId, child.parentId);
  if (!parent || parent.archivedAt !== null || parent.assigneeId === null) return;
  const all = await issueRepo.listProjectHierarchy(actor.orgId, parent.projectId);
  const descendants = collectDescendants(all, parent.id).filter((item) => item.archivedAt === null);
  if (descendants.some(isOpen)) return;
  await notify(actor.orgId, "sub_issues_completed", [parent.assigneeId], {
    title: "Sub-issues completed",
    body: `All sub-issues of issue ${parent.id} are complete`,
    href: `/issues/${parent.id}`,
    actorId: actor.userId,
  });
}
